 @Test public void permutationPreservesCarriersAndRejectsIncompleteOrStaleInput(){
  var a=new php.runtime.memory.ArrayMemory();a.put("z",php.runtime.memory.LongMemory.valueOf(3));a.put("a",php.runtime.memory.LongMemory.valueOf(1));
  var z=a.getByScalar("z");var v=a.getByScalar("a");
  try{a.reorderKeys(java.util.List.of("a","a"));fail("duplicate permutation");}catch(IllegalArgumentException expected){}
  assertSame(z,a.getByScalar("z"));assertSame(v,a.getByScalar("a"));assertEquals("z",keys(a).get(0).toString());
  a.reorderKeys(java.util.List.of("a","z"));assertSame(z,a.getByScalar("z"));assertSame(v,a.getByScalar("a"));assertEquals("a",keys(a).get(0).toString());
  try{a.reorderKeys(java.util.List.of("a"));fail("incomplete permutation");}catch(IllegalArgumentException expected){}
  var changing=new java.util.AbstractList<Object>(){public int size(){return 2;}public Object get(int i){if(i==0)a.put("new",php.runtime.Memory.NULL);return i==0?"a":"z";}};
  try{a.reorderKeys(changing);fail("stale permutation");}catch(IllegalArgumentException expected){}
  assertEquals(3,a.size());assertEquals("a",keys(a).get(0).toString());assertEquals("new",keys(a).get(2).toString());
 }
 private static java.util.List<Object> keys(php.runtime.memory.ArrayMemory a){
  var result=new java.util.ArrayList<Object>();var iterator=a.foreachIterator(false,false);while(iterator.next())result.add(iterator.getKey());return result;
 }
